# Concept Network {#sec-rede}

The graph below shows the **30 most connected concepts** and the relations between them. Node size reflects the number of connections; colours represent thematic topics.

::: {#cell-fig-network .cell execution_count=12}
``` {.python .cell-code}
import networkx as nx

G = nx.DiGraph()
for _, row in chains.iterrows():
    G.add_edge(row["from_code"], row["to_code"], relation=row["relation"])

degree_dict = dict(G.degree())
top30_nodes = sorted(degree_dict, key=degree_dict.get, reverse=True)[:30]
subG = G.subgraph(top30_nodes).copy()

pos = nx.spring_layout(subG, k=2.5, iterations=80, seed=42)

onto_topic_map = onto.set_index("chain")["topic"].to_dict()

node_x, node_y, node_text, node_size, node_color = [], [], [], [], []
topic_list = sorted(set(onto_topic_map.get(n, "Other") for n in subG.nodes()))
topic_color_map = {t: i for i, t in enumerate(topic_list)}

for node in subG.nodes():
    x, y = pos[node]
    node_x.append(x)
    node_y.append(y)
    deg = degree_dict[node]
    topic = onto_topic_map.get(node, "Other")
    node_text.append(f"{node}<br>Connections: {deg}<br>Topic: {topic}")
    node_size.append(max(15, min(60, deg * 0.8)))
    node_color.append(topic_color_map.get(topic, 0))

edge_traces = []
for u, v, data in subG.edges(data=True):
    x0, y0 = pos[u]
    x1, y1 = pos[v]
    edge_traces.append(go.Scatter(
        x=[x0, x1, None], y=[y0, y1, None],
        mode="lines",
        line=dict(width=0.5, color="#ccc"),
        hoverinfo="none",
        showlegend=False,
    ))

node_trace = go.Scatter(
    x=node_x, y=node_y,
    mode="markers+text",
    text=[n for n in subG.nodes()],
