# High-confidence Concepts {#sec-high-confidence}

The table lists the concepts classified with **HIGH confidence** --- those appearing with high frequency across multiple independent sources. Each row shows the full multidimensional classification.

::: {#tbl-high-confidence .cell tbl-cap='HIGH-confidence concepts: the empirical pillars of the field.' execution_count=13}
``` {.python .cell-code}
high_conf = onto[onto["confidence"] == "HIGH"].copy()
high_conf["aspect_label"] = high_conf["aspect"].map(aspect_labels)
high_conf["dim_label"] = high_conf["dimension"].map(dim_labels)

high_conf = high_conf.merge(
    concept_stats.reset_index().rename(columns={"concept": "chain"}),
    on="chain", how="left"
)

display_cols = ["chain", "topic", "aspect_label", "dim_label", "frequency", "sources", "reasoning"]
display_names = {
    "chain": "Concept", "topic": "Topic", "aspect_label": "Modal aspect",
    "dim_label": "Dimension", "frequency": "Freq.", "sources": "Sources",
    "reasoning": "Justification",
}

table = high_conf[display_cols].rename(columns=display_names)
table = table.sort_values("Freq.", ascending=False)
table["Freq."] = table["Freq."].fillna(0).astype(int)
table["Sources"] = table["Sources"].fillna(0).astype(int)

display(Markdown(f"**{len(table)} concepts with HIGH confidence:**"))
display(
    table.style
    .hide(axis="index")
    .background_gradient(subset=["Freq."], cmap="Greens")
    .background_gradient(subset=["Sources"], cmap="Blues")
    .set_properties(**{"text-align": "left", "font-size": "11px"})
    .set_table_styles([
        {"selector": "th", "props": [("text-align", "left"), ("font-weight", "bold")]}
    ])
)
